// these are served by the storefront's own /public/placeholders directory.
const STOREFRONT_URL = process.env.DEMO_STOREFRONT_URL ?? 'http://localhost:3000';
const ph = (file) => `${STOREFRONT_URL}/placeholders/${file}`;
const APPAREL_CARE = ['Machine wash cold with like colours', 'Do not bleach', 'Tumble dry low', 'Warm iron if needed'];
const DELICATE_CARE = ['Hand wash cold, separately', 'Do not wring', 'Dry flat in shade', 'Cool iron on reverse'];
const LEATHER_CARE = ['Wipe clean with a dry cloth', 'Keep away from water and direct heat', 'Use a leather conditioner occasionally', 'Store with a shoe tree / belt rolled, not folded'];
const FRAGRANCE_CARE = ['Store upright in a cool, dry place away from direct sunlight', 'Keep the cap on when not in use'];

let badgeCycle = 0;
function nextBadges() {
  // Rotates so badges are spread across the catalogue, never on every item.
  badgeCycle += 1;
  if (badgeCycle % 5 === 0) return ['BESTSELLER'];
  if (badgeCycle % 7 === 0) return ['NEW'];
  return [];
}

/** Even apparel sizing with a deliberate mix of available / low-stock / out-of-stock. */
function apparelSizes(pattern = 'STD') {
  const RUNS = {
    STD: ['S', 'M', 'L', 'XL'],
    WIDE: ['XS', 'S', 'M', 'L', 'XL', 'XXL'],
  };
  const stockPlan = { full: 28, low: 2, out: 0 };
  const plans = {
    STD: ['full', 'full', 'low', 'out'],
    WIDE: ['out', 'full', 'full', 'full', 'low', 'out'],
  };
  const sizes = RUNS[pattern];
  const plan = plans[pattern];
  return sizes.map((size, i) => {
    const state = plan[i];
    return state === 'out' ? { size, inStock: false } : { size, inStock: true, stockCount: stockPlan[state] + i };
  });
}

function shoeSizes() {
  return ['UK6', 'UK7', 'UK8', 'UK9', 'UK10', 'UK11'].map((size, i) => {
    if (i === 5) return { size, inStock: false };
    if (i === 4) return { size, inStock: true, stockCount: 3 };
    return { size, inStock: true, stockCount: 14 + i * 2 };
  });
}

function beltSizes() {
  return ['32', '34', '36', '38', '40'].map((size, i) => {
    if (i === 4) return { size, inStock: false };
    if (i === 3) return { size, inStock: true, stockCount: 2 };
    return { size, inStock: true, stockCount: 20 + i * 3 };
  });
}

function fragranceSizes() {
  return [
    { size: '50ml', inStock: true, stockCount: 18 },
    { size: '100ml', inStock: true, stockCount: 3 },
  ];
}

function pricing(selling, mrp) {
  const discountPercent = Math.round((1 - selling / mrp) * 100);
  return { price: selling, mrp, discountPercent };
}

