function sizesFor(p) {
  if (p.productType === 'footwear') return shoeSizes();
  if (p.productType === 'belt') return beltSizes();
  if (p.productType === 'fragrance') return fragranceSizes();
  return apparelSizes(p.category === 'Denims' ? 'STD' : 'STD');
}

function careFor(p) {
  if (p.productType === 'footwear' || p.productType === 'belt') return LEATHER_CARE;
  if (p.productType === 'fragrance') return FRAGRANCE_CARE;
  return p.fabric && /silk|crepe|satin|chikankari/i.test(p.fabric) ? DELICATE_CARE : APPAREL_CARE;
}

function buildProduct(p) {
  const sizes = sizesFor(p);
  const customAttributes = {};
  if (p.productType === 'footwear') customAttributes.closureType = p.closureType;
  if (p.productType === 'belt') { customAttributes.material = p.material; customAttributes.buckleType = p.buckleType; }
  if (p.productType === 'fragrance') {
    customAttributes.fragranceName = p.fragranceName;
    customAttributes.concentration = p.concentration;
    customAttributes.topNotes = p.topNotes;
    customAttributes.heartNotes = p.heartNotes;
    customAttributes.baseNotes = p.baseNotes;
  }
  return {
    id: p.id,
    title: p.title,
    slug: `${p.id}-${p.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`,
    subtitle: p.subtitle,
    gender: WOMEN.includes(p) ? 'women' : 'men',
    category: p.category,
    collection: p.collection,
    additionalCollections: p.additionalCollections ?? [],
    productType: p.productType,
    price: p.price, mrp: p.mrp, discountPercent: p.discountPercent,
    colors: p.colors.map((c) => ({ name: c.name, hex: c.hex, images: [c.image] })),
    sizes,
    fit: p.fit ?? undefined,
    fabric: p.fabric ?? undefined,
    care: careFor(p),
    occasion: p.occasion ?? undefined,
    badges: nextBadges(),
    details: p.details,
    customAttributes,
  };
}

const PRODUCTS = [...MEN, ...WOMEN].map(buildProduct);

